const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI financial graph arbitrator for Mana Split. In group expenses (societies, flatmates, sports tournaments), residents incur complex circular debts (A owes B, B owes C, C owes A). Minimize total transaction count using graph debt simplification and output optimized settlement instructions with UPI payment links.

Analyze the input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{
  "groupId": "SPLIT-GRP-FLAT-402",
  "originalTransactionCount": 14,
  "minimizedTransactionCount": 4,
  "totalVolumeRupees": 12850,
  "settlementPlan": [
    { "fromResident": "Rahul Sharma (B-402)", "toResident": "Vikas Rao (A-102)", "amount": 2450, "upiId": "vikas@okicici", "purpose": "Diwali Gala & Society Pool Settle" },
    { "fromResident": "Deepa Nair (C-504)", "toResident": "Anand V (D-201)", "amount": 1800, "upiId": "anand@okhdfcbank", "purpose": "Weekend Sports Court & Food Split" }
  ],
  "efficiencySavingsSummary": "Reduced 14 fragmented peer-to-peer transfers into 4 direct net settlements, saving 71% transaction friction."
}

Rules:
- Return pure JSON only, no markdown wrapping.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
